select public.portco_profile_upsert($pp$[{"name":"Mamezo","website":"https://mamezo.tech/","description":"MAMEZO is a Tokyo-headquartered IT consulting firm that helps companies modernize IT systems, design digital platforms and system architecture, and build capabilities in AI, robotics and cloud adoption.","sector":"Technology services","subsector":"IT consulting / AI and robotics engineering","country":"Japan","founded_year":1999,"business_model":"B2B","employees":894,"employees_text":"従業員数 894人 ＊2026年4月1日現在","employees_as_of":"2026-04-01","revenue":10551965000,"revenue_currency":"JPY","revenue_period":"FY2025 (12 months to 2025-03-31)","ebitda":2152151000,"ebitda_currency":"JPY","ebitda_period":"FY2025 (12 months to 2025-03-31)","ebitda_basis":"derived","leaders":[{"role":"ceo","name":"Tetsuya Nakahara (中原 徹也)","title":"President & CEO (代表取締役社長)","source_url":"https://mamezo.tech/corporate/","source_kind":"company","evidence":"役員 代表取締役社長　中原 徹也"},{"role":"other","name":"泉 健憲","title":"Director, General Manager of Administration Division (取締役管理本部本部長)","source_url":"https://mamezo.tech/cms/wp-content/uploads/2026/05/2026.04.13tk.pdf","source_kind":"filing","evidence":"問合せ先 取締役管理本部本部長 泉 健憲"}],"notes":"Listed on TSE Growth (202A) from June 2024 as Mamezo Digital Holdings; four group companies merged into MAMEZO Co., Ltd. on 2025-10-01. Founded year is the core Mamezou business (1999); the current legal entity (formerly Mamezo Digital Holdings) was established 2020-11-11. Revenue is consolidated net sales (売上高) from the FY ended March 2025 earnings release (決算短信), issued under the former name 株式会社豆蔵デジタルホールディングス. EBITDA is derived: operating profit JPY 2,070,328k + depreciation (減価償却費, cash flow statement) JPY 81,823k; the statement shows no separate goodwill amortisation line. Delisted 2026-04-14 after EQT's tender offer. No published contact email (web form only). The company's English page writes the CEO's name 'Nakahara Tetsuya'; the administration head is given in kanji only, as filed.","sources":{"description":{"url":"https://eqtgroup.com/news/eqt-to-launch-usd-371-million-tender-offer-for-mamezo-2026-01-23","name":"EQT","kind":"sponsor","as_of":"2026-01-23","evidence":"Headquartered in Tokyo, MAMEZO is a leading IT consulting firm that helps companies modernize IT systems, design digital platforms and system architecture, and enhance their organization capabilities to work with new technologies, including AI and cloud adoption."},"employees":{"url":"https://mamezo.tech/corporate/","name":"MAMEZO","kind":"company","as_of":"2026-04-01","evidence":"従業員数 894人 ＊2026年4月1日現在"},"founded_year":{"url":"https://mamezo.tech/home/encorporate/","name":"MAMEZO","kind":"company","as_of":null,"evidence":"Mamezou, the core of our Business, was launched in 1999 to promote the penetration of software engineering, object-oriented technologies included, into industries and companies."},"country":{"url":"https://mamezo.tech/home/encorporate/","name":"MAMEZO","kind":"company","as_of":null,"evidence":"Address Shinjuku Mitsui Bldg. 34F, Nishi-Shinjuku 2-1-1, Shinjuku-ku, Tokyo 163-0434,JAPAN"},"revenue":{"url":"https://mamezo.tech/cms/wp-content/uploads/2026/05/kt2025.05.12.pdf","name":"Mamezo Digital Holdings FY3/2025 決算短信 (TSE filing)","kind":"filing","as_of":"2025-05-12","evidence":"（連結損益計算書）（単位：千円）売上高 9,586,457 10,551,965 (current year: 自2024年４月１日 至2025年３月31日)"},"ebitda":{"url":"https://mamezo.tech/cms/wp-content/uploads/2026/05/kt2025.05.12.pdf","name":"Mamezo Digital Holdings FY3/2025 決算短信 (TSE filing)","kind":"filing","as_of":"2025-05-12","evidence":"営業利益 1,799,161 2,070,328 ; 減価償却費 100,518 81,823 (単位：千円, current year to 2025-03-31) -> 2,070,328 + 81,823 = 2,152,151 thousand yen"},"business_model":{"url":"https://eqtgroup.com/news/eqt-to-launch-usd-371-million-tender-offer-for-mamezo-2026-01-23","name":"EQT","kind":"sponsor","as_of":"2026-01-23","evidence":"The Company works closely with clients in the manufacturing, automotive, and financial services sectors"},"sector":{"url":"https://eqtgroup.com/about/current-portfolio/mamezo","name":"EQT","kind":"sponsor","as_of":null,"evidence":"Sector Tech Services Country Japan Fund BPEA EQT Mid-Market Growth Entry 2026"}},"holding":{"sponsor":"EQT AB","status":"current","status_note":"Taken private by BPEA EQT Mid-Market Growth Partnership via tender offer (closed 2026-03-10); delisted from TSE 2026-04-14","asset_class":"Private equity","deal_type":"Take-private","value_creation_plan":"Following completion, EQT expects to acquire full ownership of MAMEZO to support the Company's ongoing operations and strategic priorities, leveraging its track record in technology-enabled services and long-standing presence in Japan, and will collaborate with Itochu Corporation as a strategic partner to drive long-term value.","value_creation_source_url":"https://eqtgroup.com/news/eqt-to-launch-usd-371-million-tender-offer-for-mamezo-2026-01-23","notes":"USD 371 million tender offer at JPY 3,551 per share announced 2026-01-23 through offeror Roodhalsgans 1 K.K.; EQT's first IT services investment in Japan. Responsible adviser per EQT: Tetsuro Onitsuka."}},{"name":"Liberty Waste Solutions","website":"https://libertywastesolutions.com/","description":"Liberty Waste Solutions provides full-service waste management and recycling for commercial and residential customers in North Carolina, operating hauling divisions, transfer stations and landfills.","sector":"Environmental services","subsector":"Solid waste collection, recycling and disposal","country":"United States","business_model":"B2B and B2C","email":"office@libertywastesolutions.com","email_type":"generic","leaders":[{"role":"ceo","name":"Rick Prather","title":"CEO","source_url":"https://libertywastesolutions.com/about/","source_kind":"company","evidence":"Meet the Liberty Waste Solutions Team | Rick Prather | CEO"},{"role":"cfo","name":"Phil Rado","title":"CFO","source_url":"https://libertywastesolutions.com/about/","source_kind":"company","evidence":"Phil Rado | CFO"}],"notes":"Headquartered in Raleigh, NC (per former owner Allied Industrial Partners). Formed by combining 13 companies, including Wall Recycling, which rebranded under the Liberty name. Rick Prather is also named CEO in TPG's June 2026 release. No employee count, revenue or EBITDA published; TPG did not disclose terms.","sources":{"description":{"url":"https://libertywastesolutions.com/about/","name":"Liberty Waste Solutions","kind":"company","as_of":null,"evidence":"Liberty Waste Solutions is the Triangle’s largest recycling company. We provide full-service waste management and recycling for both commercial and consumer needs in Eastern North Carolina."},"business_model":{"url":"https://libertywastesolutions.com/about/","name":"Liberty Waste Solutions","kind":"company","as_of":null,"evidence":"We provide full-service waste management and recycling for both commercial and consumer needs in Eastern North Carolina."},"email":{"url":"https://libertywastesolutions.com/","name":"Liberty Waste Solutions","kind":"company","as_of":null,"evidence":"(919) 582 - 7777 office@libertywastesolutions.com"},"country":{"url":"https://www.alliedindustrialpartners.com/portfolio","name":"Allied Industrial Partners","kind":"sponsor","as_of":null,"evidence":"Realized Investments | Waste Eliminator | Atlanta, GA | Liberty Waste Solutions | Raleigh, NC"},"sector":{"url":"https://www.tpg.com/news-and-insights/tpg-to-acquire-waste-eliminator-and-liberty-waste-solutions-from-allied-industrial-partners-to-create-a-sustainable-waste-infrastructure-player","name":"TPG","kind":"sponsor","as_of":"2026-06-17","evidence":"Liberty Waste Solutions, a provider of integrated waste and recycling solutions in North Carolina."}},"holding":{"sponsor":"TPG","status":"current","status_note":"Acquired from Allied Industrial Partners via TPG Transition Infrastructure (agreement signed June 2026, combined with Waste Eliminator)","asset_class":"Infrastructure","deal_type":"Secondary buyout","value_creation_plan":"TPG is combining Liberty Waste Solutions with Waste Eliminator to create a regional waste infrastructure provider across the Southeastern U.S., and plans to support continued investment in landfill diversion, composting and recycling throughout its ownership.","value_creation_source_url":"https://www.tpg.com/news-and-insights/tpg-to-acquire-waste-eliminator-and-liberty-waste-solutions-from-allied-industrial-partners-to-create-a-sustainable-waste-infrastructure-player","notes":"Announced 2026-06-17; closing expected by Q3 2026; terms not disclosed. Third transaction in TPG's inaugural Transition Infrastructure fund. Allied Industrial Partners now lists Liberty Waste Solutions under Realized Investments. Combined platform: 14 permitted facilities and more than 500 fleet vehicles."}},{"name":"Andera","website":"https://www.andera.ai/","description":"Andera is building the AI-native platform to automate internal audit, offering AI-native GRC and controls testing that turns evidence into audit-ready workpapers.","sector":"Software","subsector":"AI for audit, GRC and controls testing","founded_year":2024,"business_model":"B2B SaaS","email":"team@andera.ai","email_type":"generic","leaders":[{"role":"ceo","name":"Aryo Patel","title":"CEO and Co-founder","source_url":"https://lsvp.com/stories/audits-moment-has-arrived-why-we-invested-in-andera/","source_kind":"sponsor","evidence":"Aryo Patel (CEO and Co-founder) came to this problem from the intersection of finance and AI infrastructure"},{"role":"other","name":"Tinah Hong","title":"CTO and Co-founder","source_url":"https://lsvp.com/stories/audits-moment-has-arrived-why-we-invested-in-andera/","source_kind":"sponsor","evidence":"Tinah Hong (CTO and Co-founder) has been close friends with Aryo since middle school in Chicago"}],"notes":"Raised a USD 37M Series A in June 2026 led by Lightspeed, joined by Bain Capital Ventures; A* led the seed round. Founded 2024 (A* met the founders in October 2024 'when Andera was just two months old'). All open roles on its careers page are on-site in San Francisco, but the company does not state its headquarters. No employee count, revenue or EBITDA published.","sources":{"description":{"url":"https://lsvp.com/stories/audits-moment-has-arrived-why-we-invested-in-andera/","name":"Lightspeed Venture Partners","kind":"sponsor","as_of":"2026-06-17","evidence":"Lightspeed is leading a $37M Series A in Andera , the company building the AI-native platform to automate internal audit."},"founded_year":{"url":"https://a-star.co/news/andera","name":"A* (investor)","kind":"sponsor","as_of":"2026-07-20","evidence":"We first met Aryo Patel and Tinah Hong in October 2024, when Andera was just two months old."},"business_model":{"url":"https://www.andera.ai/","name":"Andera","kind":"company","as_of":null,"evidence":"Streamline your audits with the first AI-native GRC and testing platform ... Book a demo"},"email":{"url":"https://www.andera.ai/","name":"Andera","kind":"company","as_of":null,"evidence":"mailto:team@andera.ai (footer 'Contact')"},"sector":{"url":"https://baincapitalventures.com/portfolio/","name":"Bain Capital Ventures","kind":"sponsor","as_of":null,"evidence":"Andera | Building the AI-native platform to automate internal audit | C. Melas-Kyriazi | Ryan Kim | Applied AI | Early | 2026"}},"holding":{"sponsor":"Bain Capital","status":"current","status_note":"Bain Capital Ventures joined the USD 37M Series A led by Lightspeed (June 2026)","asset_class":"Venture capital","deal_type":"Venture round","notes":"Listed on Bain Capital Ventures' portfolio as Applied AI, Early stage, 2026 (deal leads C. Melas-Kyriazi and Ryan Kim). BCV's participation is stated by co-investor A*; no BCV announcement found, so no value-creation plan recorded."}},{"name":"Gaming Laboratories International","website":"https://gaminglabs.com/","description":"GLI is the global leader in testing, certification and cybersecurity services to the global gaming industry, servicing over 710 regulated gaming jurisdictions worldwide.","sector":"Business services","subsector":"Gaming testing, inspection and certification; cybersecurity","country":"United States","founded_year":1989,"business_model":"B2B","employees":1500,"employees_text":"over 1,500 employees globally","employees_as_of":"2026-06-22","leaders":[{"role":"ceo","name":"James Maida","title":"President & CEO","source_url":"https://gaminglabs.com/about-us/","source_kind":"company","evidence":"Executive Leadership Team | James Maida | President & CEO"},{"role":"cfo","name":"Bruce Hecht","title":"Chief Financial Officer","source_url":"https://gaminglabs.com/about-us/","source_kind":"company","evidence":"Bruce Hecht | Chief Financial Officer"},{"role":"other","name":"Mackenzie Haugh","title":"Chief Delivery Officer","source_url":"https://gaminglabs.com/about-us/","source_kind":"company","evidence":"Mackenzie Haugh | Chief Delivery Officer"},{"role":"managing_director","name":"Richard Howarth","title":"Managing Director - APAC","source_url":"https://gaminglabs.com/about-us/","source_kind":"company","evidence":"Richard Howarth | Managing Director - APAC"},{"role":"managing_director","name":"James Boje","title":"Managing Director, EMEIA","source_url":"https://gaminglabs.com/about-us/","source_kind":"company","evidence":"James Boje | Managing Director, EMEIA"},{"role":"managing_director","name":"Salim L. Adatia","title":"Managing Director, Canada","source_url":"https://gaminglabs.com/about-us/","source_kind":"company","evidence":"Salim L. Adatia | Managing Director, Canada"}],"notes":"Founded in 1989 by James Maida and Paul Magno; headquartered in Lakewood, New Jersey. CVC is GLI's first external investor (June 2026). GLI lists no COO (Mackenzie Haugh is Chief Delivery Officer). No contact email published (web form only). No revenue or EBITDA disclosed.","sources":{"description":{"url":"https://www.cvc.com/media/news/2026/gaming-laboratories-international-g